package com.fluxisai.subscription;
import java.net.URI; import java.util.UUID; import com.fluxisai.common.web.PageResponse; import jakarta.validation.Valid; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.support.ServletUriComponentsBuilder;
@RestController @RequestMapping("/api/subscriptions") public class SubscriptionController {private final SubscriptionService service;public SubscriptionController(SubscriptionService s){service=s;} @PostMapping public ResponseEntity<SubscriptionResponse> create(@Valid @RequestBody SubscriptionRequest r){var c=service.create(r);URI location=ServletUriComponentsBuilder.fromCurrentRequest().path("/{id}").buildAndExpand(c.id()).toUri();return ResponseEntity.created(location).body(c);}@GetMapping public PageResponse<SubscriptionResponse> list(@PageableDefault(size=50,sort="renewalDate",direction=Sort.Direction.ASC)Pageable p){return service.list(p);}@GetMapping("/summary") public SubscriptionSummaryResponse summary(){return service.summary();}@GetMapping("/{id}") public SubscriptionResponse get(@PathVariable UUID id){return service.get(id);}@PutMapping("/{id}") public SubscriptionResponse update(@PathVariable UUID id,@Valid @RequestBody SubscriptionRequest r){return service.update(id,r);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable UUID id){service.delete(id);}}
